# PTX source for element‑wise sigmoid on fp16 tensors (A100, sm_80)
PTX_SOURCE = r'''
.version 7.2
.target sm_80
.address_size 64

.visible .entry sigmoid_kernel(
    .param .u64   x_ptr,
    .param .u64   y_ptr,
    .param .u32   N
)
{
    // Load parameters
    .reg .u64   %rdx;
    .reg .u64   %rdy;
    .reg .u32   %rN;
    ld.param.u64    %rdx, [x_ptr];
    ld.param.u64    %rdy, [y_ptr];
    ld.param.u32    %rN,  [N];

    // Thread index
    .reg .u32   %tid, %blk, %grid, %idx, %stride;
    mov.u32 %tid,   %tid.x;
    mov.u32 %blk,   %ctaid.x;
    mov.u32 %grid,  %nctaid.x;

    // Compute global linear index and stride
    mad.lo.u32 %idx, %blk, %ntid.x, %tid;            // idx = blockIdx.x * blockDim.x + threadIdx.x
    mul.lo.u32 %stride, %grid, %ntid.x;              // stride = gridDim.x * blockDim.x

    // Constants in registers
    .reg .f32   %c_one, %c_inv_ln2;
    mov.f32 %c_one, 1.0;
    mov.f32 %c_inv_ln2, 1.4426950408889634;   // 1/ln(2)

    // Loop over elements
    .reg .u64   %src, %dst;
    .reg .b16   %h_in;
    .reg .f32   %x_f, %neg_f, %a_f, %exp_f, %den_f, %y_f;

L_LOOP:
    setp.ge.u32   %p_exit, %idx, %rN;
    @%p_exit bra   L_DONE;

    // Load half element
    mul.wide.u64  %src, %rdx, %idx;
    ld.global.b16 %h_in, [%src];

    // Convert to fp32
    cvt.rn.f32.f16 %x_f, %h_in;

    // neg = -x
    neg.f32 %neg_f, %x_f;

    // a = neg * (1/ln2)
    mul.f32 %a_f, %neg_f, %c_inv_ln2;

    // exp(neg) ≈ 2^a   (ex2.approx)
    ex2.approx.f32 %exp_f, %a_f;

    // denominator = 1 + exp
    add.f32 %den_f, %c_one, %exp_f;

    // y = 1 / denominator   (rcp.approx)
    rcp.approx.f32 %y_f, %den_f;

    // Convert back to half
    cvt.rn.f16.f32 %h_in, %y_f;

    // Store result
    mul.wide.u64  %dst, %rdy, %idx;
    st.global.b16 [%dst], %h_in;

    // Next element
    add.u32 %idx, %idx, %stride;
    bra L_LOOP;

L_DONE:
    ret;
}
'''
# -------------------------------------------------------------
# Model wrapper that uses the PTX kernel
import torch

class ModelNew:
    def __init__(self):
        # Load PTX module (provided by the harness)
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, inputs):
        x = inputs[0]                     # fp16 tensor
        assert x.dtype == torch.float16

        y = torch.empty_like(x)           # output tensor

        # Prepare launch configuration
        total_elems = x.numel()
        threads_per_block = 256
        blocks = (total_elems + threads_per_block - 1) // threads_per_block

        # Kernel arguments: pointers and size (as 32‑bit)
        args = [
            x.data_ptr(),
            y.data_ptr(),
            total_elems
        ]

        # Launch the kernel
        ptx_launch(
            self.module,
            "sigmoid_kernel",
            grid=(blocks, 1, 1),
            block=(threads_per_block, 1, 1),
            args=args
        )

        return [y]
